using Microsoft.Xna.Framework;
namespace BluewaterHaul;
public static class PlaceIdentity {
 public static string District(Vector2 p)=>p.X< -5200&&p.Y< -950?"POINT EDWARD":p.Y< -1850&&p.X< -3500?"LAKE HURON / CANATARA":p.X< -4650&&p.Y> -500&&p.Y<1850?"DOWNTOWN / WATERFRONT":Vector2.DistanceSquared(p,new(-4274,1547))<650*650?"MITTON VILLAGE":p.Y>2200?"SOUTH SARNIA":p.X> -1600&&p.Y> -500&&p.Y<1600?"LONDON ROAD / COLLEGE": "SARNIA NEIGHBOURHOODS";
 public static void Prepare(WorldData w){
  foreach(var b in w.Buildings){float minx=b.Points.Min(p=>p[0]),maxx=b.Points.Max(p=>p[0]),minz=b.Points.Min(p=>p[1]),maxz=b.Points.Max(p=>p[1]);b.Box=new(minx,minz,maxx-minx,maxz-minz);float area=b.Box.Width*b.Box.Height;var p=Geo.V(b.Center);
   b.Style=b.Kind switch{"industrial" or "warehouse" or "car_repair" or "garage"=>"warehouse","house" or "detached" or "residential"=>"house","apartments"=>"apartments","townhall"=>"civic","library"=>"library","school" or "college"=>"school","hospital" or "clinic"=>"hospital","place_of_worship"=>b.BuildingType=="church"?"church":"civic","church"=>"church","roof"=>"canopy","yes"=>"unknown",_=>"shop"};
   if(b.Style=="unknown"){if(area<350)b.Style="house";else if(area>1500&&(p.Y>2100||b.BuildingType=="industrial"))b.Style="warehouse";else if(area>2200)b.Style="large";else if(p.X< -4700&&p.Y> -200&&p.Y<1700)b.Style="shop";else b.Style="apartments";}
   if(!b.HeightKnown)b.Height=b.Style switch{"house"=>b.Id%3==0?3.8f:5.8f,"warehouse"=>7,"hospital"=>15,"apartments"=>9,"large"=>8,_=>6};
   b.Landmark=b.Name=="Sarnia City Hall"?"cityhall":b.Id==196943642?"library":b.Name.Contains("Imperial Theatre",StringComparison.OrdinalIgnoreCase)?"theatre":"";
  }
  foreach(var (name,key) in new[]{("Bluewater Health - Sarnia","hospital"),("Lambton College","college"),("Imperial Theatre","theatre")}){var poi=w.Pois.FirstOrDefault(p=>p.Name==name);if(poi==null)continue;var p=Geo.V(poi.Point);var b=w.Buildings.FirstOrDefault(b=>Geo.Contains(b.Points,p));if(b!=null){b.Landmark=key;b.Style=key=="hospital"?"hospital":key=="college"?"school":"shop";}}
  foreach(var b in w.Buildings){if(b.BuildingType=="college"){b.Landmark="college";b.Style="school";}if(b.BuildingType=="hospital"&&Vector2.DistanceSquared(Geo.V(b.Center),new(-3683.87f,509.2f))<500*500){b.Landmark="hospital";b.Style="hospital";if(!b.HeightKnown)b.Height=15;}}
  // Heritage corner evidence + supplied footprint, explicitly recorded as an inferred match.
  var law=w.Buildings.FirstOrDefault(b=>b.Id==1526503538);if(law!=null){law.Landmark="lawrence";law.Style="heritage";if(!law.HeightKnown)law.Height=8;}
 }
}
public static class Architecture {
