 public static void Beam(MeshBuilder m,Vector3 a,Vector3 b,float radius,Color c){var d=b-a;if(d.LengthSquared()<.001f)return;d.Normalize();var u=Vector3.Cross(d,Math.Abs(d.Y)>.9f?Vector3.UnitX:Vector3.Up);u.Normalize();u*=radius;var v=Vector3.Normalize(Vector3.Cross(d,u))*radius;var aa=new[]{a-u-v,a+u-v,a+u+v,a-u+v};var bb=new[]{b-u-v,b+u-v,b+u+v,b-u+v};for(int i=0;i<4;i++)m.Quad(aa[i],aa[(i+1)%4],bb[(i+1)%4],bb[i],c);m.Quad(aa[0],aa[1],aa[2],aa[3],c);m.Quad(bb[0],bb[1],bb[2],bb[3],c);}
 public static (Vector2 A,Vector2 U,Vector2 Normal,float Length) Front(Building b){float best=float.MaxValue;Vector2 a=default,u=default,n=default;float len=0;for(int i=0;i<b.Points.Count;i++){var aa=Geo.V(b.Points[i]);var bb=Geo.V(b.Points[(i+1)%b.Points.Count]);float d=Vector2.DistanceSquared(Geo.Nearest(b.Door,aa,bb),b.Door);if(d>=best||(bb-aa).LengthSquared()<1)continue;best=d;a=aa;len=(bb-aa).Length();u=(bb-aa)/len;n=new(-u.Y,u.X);if(Vector2.Dot(n,Geo.V(b.Center)-(aa+bb)/2)>0)n=-n;}return(a,u,n,len);}
 public static void Building(MeshBuilder m,Building b){int seed=(int)(b.Id%997);var p=Geo.V(b.Center);Color wall=b.Style switch{"warehouse"=>new(158,171,179),"house"=>(seed%4) switch{0=>new(184,158,99),1=>new(158,84,61),2=>new(207,210,198),_=>new(124,151,164)},"heritage"=>new(150,68,48),"shop"=>new(155,91,67),"school"=>new(198,171,119),"civic"=>new(202,204,199),"library"=>new(161,79,57),"hospital"=>new(218,211,193),_=>new(176,165,142)};
  if(b.Landmark=="cityhall")wall=new(207,214,211);if(b.Style=="house"){var district=PlaceIdentity.District(p);if(district=="POINT EDWARD")wall=seed%2==0?new(211,219,209):new(128,161,172);else if(district=="MITTON VILLAGE")wall=seed%2==0?new(175,140,82):new(161,80,57);else if(district=="DOWNTOWN / WATERFRONT")wall=new(183,152,90);}float h=b.Height;
  for(int i=0;i<b.Points.Count;i++){var a=Geo.V(b.Points[i]);var e=Geo.V(b.Points[(i+1)%b.Points.Count]);var delta=e-a;float length=delta.Length();if(length<.01f)continue;var d=delta/length;var n=new Vector2(-d.Y,d.X);if(Vector2.Dot(n,p-(a+e)/2)>0)n=-n;n*=.045f;
   m.Quad(Geo.V3(a,.2f),Geo.V3(e,.2f),Geo.V3(e,h),Geo.V3(a,h),wall*(i%2==0?1:.87f));
   if(b.Style=="warehouse"){for(float x=1;x<length;x+=2.5f)Beam(m,Geo.V3(a+d*x+n,.4f),Geo.V3(a+d*x+n,h-.3f),.035f,wall*.72f);continue;}
   if(b.Style=="canopy")continue;
   float spacing=b.Style is "civic" or "hospital"?2.8f:b.Style=="house"?3.3f:3.8f;for(float y=1.25f;y<h-1;y+=3)for(float x=1.7f;x<length-1;x+=spacing){float half=b.Style=="house"?.55f:.8f;var l=a+d*(x-half)+n;var r=a+d*(x+half)+n;m.Quad(Geo.V3(l,y),Geo.V3(r,y),Geo.V3(r,y+1.35f),Geo.V3(l,y+1.35f),Glass);Beam(m,Geo.V3(l,y-.08f),Geo.V3(r,y-.08f),.08f,Trim);Beam(m,Geo.V3(l,y+1.4f),Geo.V3(r,y+1.4f),.07f,Trim);Beam(m,Geo.V3((l+r)/2,y),Geo.V3((l+r)/2,y+1.35f),.035f,Trim);if(b.Style=="house"&&seed%3==0){Beam(m,Geo.V3(l-d*.2f,y),Geo.V3(l-d*.2f,y+1.4f),.13f,new(57,85,73));Beam(m,Geo.V3(r+d*.2f,y),Geo.V3(r+d*.2f,y+1.4f),.13f,new(57,85,73));}}
   Beam(m,Geo.V3(a+n,h-.15f),Geo.V3(e+n,h-.15f),.12f,Trim);
  }
  if(b.RoofTriangles.Count>0)foreach(var t in b.RoofTriangles)m.Tri(Geo.V3(Geo.V(t[0]),h),Geo.V3(Geo.V(t[1]),h),Geo.V3(Geo.V(t[2]),h),new(72,76,81));else m.Polygon(b.Points,h,new(72,76,81));
  var front=Front(b);var door=Geo.Nearest(b.Door,front.A,front.A+front.U*front.Length)+front.Normal*.06f;var u=front.U;var normal=front.Normal;
  void Face(Vector2 q,float width,float y0,float y1,Color color){m.Quad(Geo.V3(q-u*width/2,y0),Geo.V3(q+u*width/2,y0),Geo.V3(q+u*width/2,y1),Geo.V3(q-u*width/2,y1),color);}
  if(b.Enterable){Face(door,1.1f,.15f,2.3f,new(71,53,39));Face(door+normal*.03f,.7f,1.2f,2.05f,Glass);Beam(m,Geo.V3(door-u*.65f,.1f),Geo.V3(door-u*.65f,2.45f),.07f,Trim);Beam(m,Geo.V3(door+u*.65f,.1f),Geo.V3(door+u*.65f,2.45f),.07f,Trim);Beam(m,Geo.V3(door-u*.65f,2.45f),Geo.V3(door+u*.65f,2.45f),.07f,Trim);}
  if(b.Style is "house" or "heritage"){float rise=b.Style=="heritage"?3.5f:2;bool convex=true;for(int i=0;i<b.Points.Count;i++){var a=Geo.V(b.Points[i]);var e=Geo.V(b.Points[(i+1)%b.Points.Count]);if(!Geo.Contains(b.Points,(a+e+p)/3))convex=false;}if(convex)for(int i=0;i<b.Points.Count;i++){var a=Geo.V(b.Points[i]);var e=Geo.V(b.Points[(i+1)%b.Points.Count]);m.Tri(Geo.V3(a,h),Geo.V3(e,h),Geo.V3(p,h+rise),new(65+seed%30,65+seed%15,68));}
   var chimney=p+u*Math.Min(b.Box.Width*.18f,2);m.Box(Geo.V3(chimney-new Vector2(.35f),h),Geo.V3(chimney+new Vector2(.35f),h+rise+1),new(134,75,53));
   // Open porch canopy. No solid geometry extends into the original collision footprint.
   float width=Math.Min(4,front.Length*.55f);var pa=door-u*width/2;var pe=door+u*width/2;m.Quad(Geo.V3(pa,2.5f),Geo.V3(pe,2.5f),Geo.V3(pe+normal*1.4f,2.25f),Geo.V3(pa+normal*1.4f,2.25f),new(83,97,95));foreach(var q in new[]{pa+normal*1.3f,pe+normal*1.3f})Beam(m,Geo.V3(q,.1f),Geo.V3(q,2.3f),.06f,Trim);
  }
  if(b.Style=="shop"){float width=Math.Min(front.Length*.75f,10);Face(door-u*2+normal*.04f,2.4f,.5f,2.4f,Glass);if(front.Length>7)Face(door+u*2+normal*.04f,2.4f,.5f,2.4f,Glass);var c=new Color(39+seed%60,83+seed%50,84+seed%70);var a=door-u*width/2;var e=door+u*width/2;m.Quad(Geo.V3(a,3.2f),Geo.V3(e,3.2f),Geo.V3(e+normal,2.8f),Geo.V3(a+normal,2.8f),c);Face(door+normal, width,2.6f,2.8f,c*.8f);Face(door+normal*.1f,Math.Min(front.Length*.9f,14),3.45f,4.3f,new(36,55,59));}
  if(b.Style=="warehouse"){for(float x=3;x<front.Length-2;x+=8){var q=front.A+u*x+normal*.08f;Face(q,4.5f,.2f,4.4f,new(78,85,87));for(float y=.5f;y<4.4f;y+=.45f)Beam(m,Geo.V3(q-u*2.2f,y),Geo.V3(q+u*2.2f,y),.025f,new(170,172,165));}m.Box(Geo.V3(p-new Vector2(1),h),Geo.V3(p+new Vector2(1),h+1),new(98,110,113));}
  if(b.Landmark is "cityhall" or "library" or "hospital" or "college"){float width=Math.Min(front.Length*.65f,12);var a=door-u*width/2;var e=door+u*width/2;m.Quad(Geo.V3(a,3),Geo.V3(e,3),Geo.V3(e+normal*2.5f,3),Geo.V3(a+normal*2.5f,3),Trim);Face(door+normal*.12f,width,3.6f,4.7f,new(27,73,91));foreach(var q in new[]{a+normal*2.3f,e+normal*2.3f})Beam(m,Geo.V3(q,.1f),Geo.V3(q,3),.1f,Trim);if(b.Landmark=="cityhall"){var flag=door+u*(width/2+2)+normal*2;Beam(m,Geo.V3(flag,0),Geo.V3(flag,10),.06f,Color.LightGray);var q=Geo.V3(flag,8.5f);m.Quad(q,q+Geo.V3(u*2,0),q+Geo.V3(u*2,1),q+new Vector3(0,1,0),new(202,43,48));m.Quad(q+Geo.V3(u*.6f,0)+Geo.V3(normal*.015f,0),q+Geo.V3(u*1.4f,0)+Geo.V3(normal*.015f,0),q+Geo.V3(u*1.4f,1)+Geo.V3(normal*.015f,0),q+Geo.V3(u*.6f,1)+Geo.V3(normal*.015f,0),Color.White);}}
  if(b.Landmark=="lawrence"){var tower=door-u*2.5f-normal*1.3f;if(!Geo.Contains(b.Points,tower))tower=p;float radius=1.5f;for(int i=0;i<8;i++){float t=i*MathHelper.TwoPi/8,tt=(i+1)*MathHelper.TwoPi/8;var a=tower+new Vector2(MathF.Cos(t),MathF.Sin(t))*radius;var e=tower+new Vector2(MathF.Cos(tt),MathF.Sin(tt))*radius;m.Quad(Geo.V3(a,.2f),Geo.V3(e,.2f),Geo.V3(e,h+4),Geo.V3(a,h+4),wall);m.Tri(Geo.V3(a,h+4),Geo.V3(e,h+4),Geo.V3(tower,h+7),new(65,75,78));}Beam(m,Geo.V3(tower,h+7),Geo.V3(tower,h+8),.06f,Trim);}
  if(b.Style=="church"){var q=p;Beam(m,Geo.V3(q,h),Geo.V3(q,h+6),.12f,Trim);Beam(m,Geo.V3(q-new Vector2(1,0),h+4),Geo.V3(q+new Vector2(1,0),h+4),.12f,Trim);}
 }
